    "description": "22日，玉龙县拉市海景区管理局发布官方通告：拉市海景区各马场将在2026年8月24日起暂停旅游接待服务。 通告称，为提升拉市海景区旅游服务质量，拉市海景区各马场自2026年8月24日起暂停旅游接待服务。恢复接待时间将结合提升完成情况另行通告。 据公开资料：拉市海风景区位于云南省丽江市玉龙纳西族自治县，是1998年经云南省人民政府批准建立的省级湿地自然保护区，总面积6523公顷，涵盖拉市海、文海等四个片区。",
