    "content": "最近在做 ImgPhotoEditor ，先把“去掉或替换照片背景”这条链路单独拿出来打磨。 现在的流程是：上传 JPG 、PNG 或 WebP （单张不超过 24 MB ），用一句话描述要保留的主体和背景变化，选择当前可用的模型及输出配置，生成后检查结果，再下载透明 PNG 或替换背景后的图片。 我不太想把它包装成“一键完美抠图”。头发、毛发、透明物体、反光，以及主体和背景对比度很低时，边缘仍然容易出问题。所以结果页会提醒用户放大检查，也建议在浅色和深色背景上各看一次，确认没有残留、缺口或色边。 另外边界也先说明…"
