    "content": "社交媒体上，留学生们时常就“吃饭”留下各种吐槽：商超熟食又腥又骚，炸物速食易让体重迅增，或者是买到名字和味道对不上的食材......中山大学旅游学院副教授钟淑茹曾在美国留学，曾经的她困惑“为什么美国只有大超市没有菜市场？”回国后，她又有了新的困惑，现在（国内）买菜的渠道那么多那么便利，传统菜市场为何还能存在？ 民以食为天的中国，到底有多少菜市场？也许每个城市可以有个“菜市场指数”，某种程度上可以代表一个城市的美味指数。菜市场越多的地方，食物越好吃吗？当越来越多的年轻人将逛菜市场列进旅行清单，试图从日常生活细节中寻找…"
