    "description": "中新网上海8月22日电(记者 李姝徵)8月22日，上海市公安局静安分局通报，一男子发布涉企不实信息被行政拘留。经警方调查，2026年8月19日，沈某某(男，26岁)为博取关注，采取张冠李戴的方式，将网上下载的图片发布在多个聊天群内，并编造“陕西南路某饭店将低价饮料盛装高脚杯后，以398元一杯出售”的不实信息，造成恶劣影响。目前，沈某某已被警方依法处以行政拘留。",
