    "title": "华北地区在建最大跨径提篮钢箱拱桥转入拱部施工阶段",
    "link": "http://www.news.cn/20260822/42bdf134c9cb44a594c72374acca8731/c.html",
    "pub_date": "2026-08-22 13:04:21",
    "author": "杨子春",
    "description": "近日，在天津市滨海新区西中环快速路跨海河桥工程南岸主墩施工现场，华北地区在建最大跨径提篮钢箱拱桥转入拱部施工阶段。 该工程主桥全长421.6米，桥面最大宽度达64米。建成后，将极大提升天津市滨海新区南北向道路通行能力，进一步完善天津港集疏运体系，更好服务京津冀协同发展。 作者：杨子春、张伯妍、秦小明 新华社音视频部制作",
    "content": "近日，在天津市滨海新区西中环快速路跨海河桥工程南岸主墩施工现场，华北地区在建最大跨径提篮钢箱拱桥转入拱部施工阶段。 该工程主桥全长421.6米，桥面最大宽度达64米。建成后，将极大提升天津市滨海新区南北向道路通行能力，进一步完善天津港集疏运体系，更好服务京津冀协同发展。 作者：杨子春、张伯妍、秦小明 新华社音视频部制作"
