    "content": "清晨的宁德三都澳，碧海粼粼，一座座深水网箱整齐排布。渔民宋向国捧起一尾大黄鱼，金黄的鳞片在阳光下熠熠生辉，引得游客纷纷询价。 福建宁德素有“中国大黄鱼之乡”的美誉，全产业链产值突破200亿元，全国每5条大黄鱼有4条源自这里。新华社记者近日跟随“活力中国调研行”采访团走进这片“海上牧场”，聆听一条大黄鱼背后的“耕海新声”。 上个世纪末，野生大黄鱼资源衰退，科研人员攻克人工育苗难关，让大黄鱼实现从海洋捕捞走向人工养殖的跨越。如今，现代科技让大黄鱼游上新的台阶。 “过去都是小网箱，一口平均只能产二三十吨，而且容易老化破损…"
