    "author": "谢艺观/@中国新闻网",
    "description": "近日，网上流传的一张爆料截图显示，民生人寿董事长把和自己生肖属相不合的人全部裁员。另有报道称，工作多年的员工如果学历不是一本也要被裁。对此，民生人寿客服表示，公司已对网络上的造谣内容进行证据保全。对于编造、扩散此类虚假信息的机构或个人，公司将通过法律途径追究其法律责任，提醒广大网友甄别网络信息真伪，不信谣、不传谣。公司一切信息均以官方发布内容为准。",
