    "content": "快科技8月22日消息，当地时间8月21日， 英国切斯特动物园发布消息，称一条名为“朱迪·福斯特”的23岁网纹蟒，成为世界上第一条接受人类电化学抗癌疗法并完全康复的蛇类 。 这条巨蟒体长4.5米，重达50公斤，此前饲养员发现它食欲下降、活动减少，检查确诊下颌位置长出恶性纤维肉瘤。 2024年兽医完成肿瘤切除手术，但2025年肿瘤复发，不断侵蚀颌骨，蟒蛇几乎无法进食，生命岌岌可危。 动物园兽医团队联合利物浦大学人类癌症研究专家，决定把人类临床使用的电化学疗法适配到蛇身上。 治疗过程包含手术切除肿瘤与部分病变颌骨，再通过…"
