    "content": "新华社金沙萨8月21日电（记者史彧）刚果（金）卫生部21日晚说，该国当天收到首批用于应对本轮埃博拉疫情的疫苗，这种疫苗此前获批用于预防扎伊尔型埃博拉病毒，对引发本轮疫情的本迪布焦型埃博拉病毒的效果将被评估。该国已累计报告埃博拉确诊病例5290例，其中死亡2516例。 刚果（金）卫生部说，首批16520剂Ervebo疫苗当天运抵首都金沙萨。21日至24日预计共有50120剂疫苗陆续运抵。 世界卫生组织20日发布公报说，疫苗供应国际协调小组已通知刚果（金）政府，将立即调拨首批7万剂Ervebo疫苗，其中2万剂将用于开展…"
