    "title": "美媒：美国陆军部长预计将于年底前卸任",
    "link": "http://www.news.cn/20260822/ab2cab89357845a793a2209392d92702/c.html",
    "pub_date": "2026-08-22 12:05:10",
    "author": "杨伶 熊茂伶",
    "description": "新华社华盛顿8月21日电 据美国《华尔街日报》21日报道，美国陆军部长丹尼尔·德里斯科尔预计将于年底前卸任。五角大楼和德里斯科尔的发言人均拒绝对此事予以评论。 报道援引知情人士的话说，德里斯科尔预计将于年底前卸任，甚至可能更早，原因是他与国防部长赫格塞思之间存在紧张关系且已持续数月。 知情人士透露，今年夏天，德里斯科尔一家已搬出位于弗吉尼亚州迈尔斯－亨德森霍尔联合基地的陆军部长官邸。他本人搬进基地内一处公寓，其家人搬到了北卡罗来纳州。 …",
