    "content": "新华社雅加达8月22日电（记者张怡晟）印度尼西亚总统普拉博沃21日在雅加达官邸会见外交部长王毅、国防部长董军。 普拉博沃请王毅转达对习近平主席的良好祝愿，积极评价印尼中国全面战略对话机制和“2+2”对话机制作用和成果，表示在习近平主席领导下，中国成功实现数亿人脱贫，在经济、科技、军事等领域取得不可思议的伟大成就，为全球南方国家树立了榜样，提供了很多有益启示，值得各方学习借鉴。中国对印尼平等相待，相互尊重，给予印尼宝贵的信心和支持。印尼期待同中方加强政治、经济、科技等全方位战略合作，欢迎更多中国企业来印尼投资兴业，将…"
