    "author": "",
    "description": "8月21日，社区连锁生鲜企业钱大妈国际控股有限公司向港交所递交IPO更新申报材料。最新财务数据显示，2026年上半年经调整净利润为1.04亿元，较2025年同期增长3.7%。整体毛利率从2025年上半年的11.2%稳步提升至11.5%，盈利水平稳步提升。截至2026年7月31日，全国门店达3020家。2026年上半年加盟门店日均客数近600人次，较2023年提升近6%，经营活力持续释放。",
    "content": "8月21日，社区连锁生鲜企业钱大妈国际控股有限公司向港交所递交IPO更新申报材料。最新财务数据显示，2026年上半年经调整净利润为1.04亿元，较2025年同期增长3.7%。整体毛利率从2025年上半年的11.2%稳步提升至11.5%，盈利水平稳步提升。截至2026年7月31日，全国门店达3020家。2026年上半年加盟门店日均客数近600人次，较2023年提升近6%，经营活力持续释放。"
