    "content": "随着上市公司2026年半年报的不断披露，“牛散”章建平的持股动向也逐渐清晰。据证券时报记者统计，截至目前，章建平（不排除重名可能性）二季度新进中际旭创第九大股东，同时退出多只个股前十大股东。中际旭创半年报显示，章建平新进为第九大股东，持有593.48万股。按中际旭创6月30日的收盘价1270元/股计算，章建平的持股市值超过75亿元。此外，章建平二季度还退出多只个股前十大股东，包括四川黄金、北方稀土、东材科技等。一季度末，章建平曾现身多只资源股前十大股东，除了上述四川黄金、北方稀土，还有西部材料，��部材料目前未披露…"
