    "content": "先说一下背景：我在 GG 大规模封号的前几天，用 Visa 卡购买了 GG 卡的服务，直接在 eSIM 手机上激活了。之后收到了 GG 的邮件，通过两次申诉，拿到了最终处理结果————不予退款。 于是我参考网上的教程去 Ombudsman 申诉，填了很多资料。等了大概两周成功立案，再等了大概一周，Ombudsman 和 gg 同时给我回复了邮件：GG 这边承认是误杀，给我恢复了服务，并承诺给了 10 英镑的补偿，但仍然表示他们的服务条款是英国境内使用，短期境外。 所以我是对 GG 卡不抱太大的希望，我也并不看重这 …"
