    "id": "国外-RFI 法国国际广播电台-https://www.rfi.fr/cn/%E5%9B%BD%E9%99%85/20260822-%E4%BD%A0%E5%A6%82%E4%BD%95%E8%A2%AB%E4%BA%BA%E5%B7%A5%E6%99%BA%E8%83%BD%E5%88%A9%E7%94%A8-%EF%BC%8C%E8%80%8C%E4%B8%8D%E6%98%AF%E4%BD%A0%E5%88%A9%E7%94%A8%E5%AE%83",
